{"returncode":0,"stdout":"    cmd = sys.argv[1] if len(sys.argv) > 1 else 'ratios'
    if cmd == 'iso':
        os.environ.setdefault("SIC_NOCLAMP", "1"); os.environ.setdefault("SUBCELL", "1")
        import hfc2 as H, nlguard as NG
        H.CORR = False
        CORE = [(1, 0, 2.0), (2, 0, 2.0), (2, 1, 6.0)]      # Ne core, held FIXED
        CH = [(3, 0), (3, 1), (3, 2), (4, 0), (4, 1)]
        def add(cfg, ch):
            d = {(n, l): q for n, l, q in cfg}; d[ch] = d.get(ch, 0) + 1
            return [(n, l, q) for (n, l), q in sorted(d.items())]
        zs = [int(x) for x in sys.argv[2:]] or [11, 13, 16, 20, 26]
        print(" Znuc  q   a(s->p)  a(p->d)")
        for Znuc in zs:
            g = NG.run_guarded(Znuc, CORE, 'ref')
            if not g['conv']: print(f"{Znuc:>5}  ref NO-DATA"); continue
            E0 = g['E']; D = {}
            for ch in CH:
                gg = NG.run_guarded(Znuc, add(CORE, ch), 'x')
                D[ch] = (gg['E'] - E0) if gg['conv'] else None
            try:
                a1 = (D[(3, 1)] - D[(3, 0)]) / (D[(4, 0)] - D[(3, 0)])
                a2 = (D[(3, 2)] - D[(3, 1)]) / (D[(4, 1)] - D[(3, 1)])
                print(f"{Znuc:>5} {Znuc-10:>2}  {a1:7.4f}  {a2:7.4f}")
            except TypeError:
                print(f"{Znuc:>5} {Znuc-10:>2}  incomplete (a channel did not converge)")
        return

    rows = load()
    if cmd == 'intervals':
        print("   Z   all-pairs        penetrating-only   1 in pen?  ent")
        for Z in sorted(rows):
            lo, hi, _ = interval(rows[Z]['order'])
            lp, hp, npen = interval(rows[Z]['order'], True)
            if npen < 2: continue
            f = lambda a, b: f"[{a:6.2f},{b:6.2f}]" if b < 1e8 else f"[{a:6.2f},  inf]"
            print(f"{Z:>5}  {f(lo,hi)}  {f(lp,hp)}      {'yes' if lp<=1<=hp else 'NO '}    {rows[Z]['ent']}")
    elif cmd == 'sources':
        src = {}
        for Z in sorted(rows):
            ch = [(t,) + nl(t) for t, D in rows[Z]['order'] if rho(t, D) > 1.5]
            for i in range(len(ch)):
                for j in range(i + 1, len(ch)):
                    ti, ni, li = ch[i]; tj, nj, lj = ch[j]; dn, dl = ni - nj, lj - li
                    if dl and abs(dn / dl - 1) < 1e-9:
                        k = (ti, tj, (ni + li) == (nj + lj), 'a<=1' if dl < 0 else 'a>=1')
                        src[k] = src.get(k, 0) + 1
        print("  pair            equal n+l   forces   rows")
        for k, v in sorted(src.items(), key=lambda x: -x[1])[:14]:
            print(f"  {k[0]:>3} over {k[1]:>3}     {str(k[2]):>5}    {k[3]:>5}   {v}")
        print(f"\n  equal-n+l share of all a=1 bounds: "
              f"{sum(v for k,v in src.items() if k[2])/sum(src.values()):.3f}")
    elif cmd == 'blocks':
        # THE s65 TEST. For each equal-n+l block, the tie-break pair is
        # A=(n,l+1) (lower n, what Madelung requires first) against B=(n+1,l).
        # Evaluate `a` AT THE Z WHERE THE BLOCK OPENS -- not at some other atom --
        # and check the prediction a<1 <=> Madelung's tie-break holds there.
        first = {}
        for Z in sorted(rows):
            t = T(*rows[Z]['ent_nl'])
            if t not in first: first[t] = Z
        print("  block  pair(A lower-n vs B)  A first?  Zopen   a@Zopen   a<1?  agree?")
        for N in range(3, 9):
            for l in range(0, 4):
                n = N - l
                if n < l + 2: continue
                A, B = T(n, l + 1), T(n + 1, l)
                if A not in first or B not in first: continue
                Afirst = first[A] < first[B]
                Zo = min(first[A], first[B])
                D = dict(rows[Zo]['order'])
                a, b, cc = T(n, l), A, B
                val = None
                if a in D and b in D and cc in D and abs(D[cc] - D[a]) > 1e-4:
                    val = (D[b] - D[a]) / (D[cc] - D[a])
                if val is None:
                    print(f"   {N}    {A:>3} vs {B:>3}       {str(Afirst):>5}   {Zo:>4}     NO-DATA")
                else:
                    agree = (val < 1) == Afirst
                    print(f"   {N}    {A:>3} vs {B:>3}       {str(Afirst):>5}   {Zo:>4}   {val:7.4f}   "
                          f"{str(val<1):>5}  {'YES' if agree else '** NO **'}")
    else:
        data = ratios(rows)
        v = [d[3] for d in data]
        print(f"  {len(data)} measurements at q=1 (neutral atoms, sealed chain)")
        print(f"  median {st.median(v):.4f}  mean {st.mean(v):.4f}  "
              f"frac >=1: {sum(1 for x in v if x>=1)/len(v):.2f}")
        print("\n  every measurement with a < 1:")
        for Z, n, l, a, dn in data:
            if a < 1: print(f"    Z={Z:>4}  {n}{'spdf'[l]}->{'spdf'[l+1]}  a={a:6.3f}  dN={dn}")
        print("\n  by core-shell-count difference dN = N_l - N_(l+1)  "
              "[THIS PREDICTOR FAILED -- see FINDING §4]")
        for dn in sorted({d[4] for d in data}):
            w = [d[3] for d in data if d[4] == dn]
            print(f"    dN={dn}  n={len(w):>3}  median {st.median(w):7.3f}  "
                  f"min {min(w):7.3f}  max {max(w):7.3f}")


if __name__ == '__main__':
    main()
